// Webhook v2 envolve o payload em .body — suporta os dois formatos
const raw = $input.first().json;
const d = raw.body || raw;

// 1 caractere basta: "oi" e "ok" são conversa, não erro. A edge function do
// app já aceita 1 — exigir 3 aqui derrubava justamente as mensagens curtas.
if (!d.question || String(d.question).trim().length < 1) {
  throw new Error('question é obrigatório');
}

function uuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
}

// artifactOutline/artifactBodies saíram: o app não tem mais documento de
// diagnóstico, então isso chegava sempre vazio.
return [{
  json: {
    conversationId: d.conversationId || uuid(),
    isNewConversation: !d.conversationId,
    question: String(d.question).trim(),
    folderIds: Array.isArray(d.folderIds) ? d.folderIds : [],
    mode: d.mode || 'rapido',
    userId: d.userId || null,
    supabaseUrl: 'https://alrnajijumqvxzmogwpy.supabase.co',
    // >>> COLE AQUI a service_role do projeto do RAG <<<
    supabaseServiceKey: 'COLE_AQUI_A_SERVICE_ROLE',
  }
}];

const d = $input.first().json;
const mode = d.mode;

// topK maior desde que o acervo virou bilíngue: parte das vagas pode ser
// ocupada pelo mesmo assunto no outro idioma.
const topK = mode === 'pesquisa' ? 24 : 12;

// 0.4 cortava o acervo em inglês inteiro: trecho em outro idioma pontua mais
// baixo por construção, não por ser pior. Calibre olhando o `similarity` que
// volta numa pergunta que você sabe estar respondida só em inglês.
const minSimilarity = 0.22;

// maxTokens saiu daqui: nunca chegava ao modelo. O teto real agora está nas
// options do nó LLM.
const modeGuidance = mode === 'pesquisa'
  ? 'MODO PESQUISA: você recebeu trechos de várias buscas relacionadas. ' +
    'Compare o que as fontes dizem, aponte convergências e divergências, e ' +
    'organize em seções com subtítulos. Quando duas fontes discordarem, ' +
    'mostre as duas em vez de escolher uma em silêncio.'
  : 'MODO RÁPIDO: no máximo 4 parágrafos curtos, ou uma lista de até 6 itens. ' +
    'Direto ao ponto: sem introdução, sem recapitular a pergunta e sem ' +
    'fechamento do tipo "espero ter ajudado". Se o assunto pedir mais ' +
    'profundidade, diga numa linha que vale usar o modo pesquisa em vez de ' +
    'alongar aqui.';

return [{ json: { ...d, topK, minSimilarity, modeGuidance } }];

const cfg = $('Code: Modo & Configs').first().json;

// Histórico: PostgREST devolve texto, do mais NOVO para o mais velho — por
// isso o reverse. Antes o nó trazia 20 sem ordenar, o que numa conversa longa
// entregava as 20 MAIS ANTIGAS e jogava fora o contexto recente.
let historico;
try { historico = JSON.parse($('HTTP: Busca Histórico').first().json.body || '[]'); }
catch (e) { historico = []; }
if (!Array.isArray(historico)) historico = [];
historico = historico.filter(m => m && m.role).reverse();

// Se o corte de 8 deixou uma resposta órfã na frente, tira: resposta sem a
// pergunta que a gerou confunde mais do que ajuda.
if (historico[0] && historico[0].role === 'assistant') historico.shift();

// Chunks: vêm como texto (responseFormat: text)
let chunks;
try { chunks = JSON.parse($('HTTP: Busca Chunks').first().json.body || '[]'); }
catch (e) { chunks = []; }
if (!Array.isArray(chunks)) chunks = [];

const context = chunks.length
  ? chunks.map((c, i) => {
      const page = c.page ? ' (página ' + c.page + ')' : '';
      return '[' + (i + 1) + '] ' + (c.title || 'Documento') + page + '\n' + c.content;
    }).join('\n\n---\n\n')
  : 'Nenhum documento encontrado.';

// Resposta antiga inteira não acrescenta nada e custa em TODA pergunta: o
// começo dela já diz do que se tratava.
const historyText = historico.length
  ? '\n\n--- Histórico ---\n' +
    historico.map(m => {
      const quem = m.role === 'user' ? 'Usuário' : 'Assistente';
      const txt = String(m.content || '');
      const corta = m.role === 'assistant' && txt.length > 600;
      return quem + ': ' + (corta ? txt.slice(0, 600) + '…' : txt);
    }).join('\n') +
    '\n--- Fim do histórico ---'
  : '';

return [{
  json: {
    question: cfg.question,
    systemPromptWithContext:
      cfg.systemPrompt + '\n\n' + cfg.modeGuidance + historyText +
      '\n\nTrechos dos documentos:\n\n' + context,
    chunks,
    conversationId: cfg.conversationId,
    userId: cfg.userId,
    mode: cfg.mode,
  }
}];

// Aceita os dois nós: o Agent devolve `output`, o Basic LLM Chain devolve
// `text`. Assim dá para trocar um pelo outro sem quebrar nada aqui.
const entrada = $input.first().json;
const answer = entrada.output || entrada.text || '';
const ctx = $('Code: Monta Prompt').first().json;
const chunks = ctx.chunks || [];

// Quais marcadores [N] aparecem na resposta
const usedMarkers = new Set();
for (const m of [...(answer.matchAll(/\[(\d{1,2})\]/g) || [])]) {
  usedMarkers.add(parseInt(m[1]));
}

// Apenas os chunks citados no texto
const citations = chunks
  .map((c, i) => ({ c, marker: i + 1 }))
  .filter(({ marker }) => usedMarkers.has(marker))
  .map(({ c, marker }) => ({
    id: c.id,
    sourceType: c.source_type || 'document',
    title: c.title || '',
    detail: c.page ? 'Página ' + c.page : (c.folder_name || ''),
    relevance: Math.round((c.similarity || 0) * 100) / 100,
    snippet: (c.content || '').slice(0, 320),
    reference: c.reference || null,
    marker,
    documentId: c.document_id || null,
    folderId: c.folder_id || null,
    folderName: c.folder_name || null,
    page: c.page || null,
  }));

const similarities = chunks.map(c => c.similarity || 0).sort((a, b) => b - a);
const top    = similarities[0] ?? 0;
const strong = similarities.filter(s => s >= 0.4).length;
const level  = (top >= 0.55 && strong >= 2) ? 'muito_alta'
             : top >= 0.5  ? 'alta'
             : top >= 0.4  ? 'media'
             : 'baixa';

// supabaseUrl/Key saíram daqui: nenhum nó abaixo usa (os saves vão por
// credencial), então a chave viajava à toa.
return [{
  json: {
    conversationId: ctx.conversationId,
    userId: ctx.userId,
    question: ctx.question,
    answer,
    citations,
    confidence: { level, score: Math.round(top * 100) / 100 },
    mode: ctx.mode,
  }
}];
